323	    #[ztracing::instrument(skip_all)]
324	    pub fn hunks_intersecting_range<'a>(
325	        &'a self,
326	        range: Range<Anchor>,
327	        buffer: &'a text::BufferSnapshot,
328	    ) -> impl 'a + Iterator<Item = DiffHunk> {
329	        let unstaged_counterpart = self.secondary_diff.as_deref();
330	        let range = range.to_offset(buffer);
331	        let filter = move |summary: &DiffHunkSummary| {
332	            let summary_range = summary.buffer_range.to_offset(buffer);
333	            let before_start = summary_range.end < range.start;
334	            let after_end = summary_range.start > range.end;
335	            !before_start && !after_end
336	        };
337	        self.hunks_intersecting_range_impl(filter, buffer, unstaged_counterpart)
338	    }
339	
340	    /// Like [`hunks_intersecting_range`], but ignores optimistic pending hunks
341	    /// (both secondary-status overrides and suppressions) and does not compute a
342	    /// secondary status.
343	    pub fn raw_hunks_intersecting_range<'a>(
344	        &'a self,
345	        range: Range<Anchor>,
346	        buffer: &'a text::BufferSnapshot,
347	    ) -> impl 'a + Iterator<Item = DiffHunk> {
348	        let range = range.to_offset(buffer);
349	        let filter = move |summary: &DiffHunkSummary| {
350	            let summary_range = summary.buffer_range.to_offset(buffer);
351	            !(summary_range.end < range.start) && !(summary_range.start > range.end)
352	        };
353	        self.hunks
354	            .filter::<_, DiffHunkSummary>(buffer, filter)
355	            .map(move |hunk| {
356	                let buffer_range = hunk.buffer_range.clone();
357	                DiffHunk {
358	                    range: buffer_range.to_point(buffer),
359	                    diff_base_byte_range: hunk.diff_base_byte_range.clone(),
360	                    buffer_range,
361	                    secondary_status: DiffHunkSecondaryStatus::NoSecondaryHunk,
362	                    base_word_diffs: hunk.base_word_diffs.clone(),
363	                    buffer_word_diffs: hunk.buffer_word_diffs.clone(),
364	                }
365	            })
366	    }
367	
368	    /// Maps a range in this diff's main buffer to the range it covers in the
369	    /// base text, expanding to whole hunks wherever the range endpoints fall
370	    /// inside or touch a hunk (`edit_for_old_position` is inclusive on both
371	    /// boundaries, matching `raw_hunks_intersecting_range`). Used by the
372	    /// index-write path to compute the index-coordinate footprint of a staging
373	    /// operation; like the raw hunks, the mapping ignores optimistic pending
374	    /// hunks.
375	    pub fn base_text_range_for_buffer_range(
376	        &self,
377	        range: Range<Anchor>,
378	        buffer: &text::BufferSnapshot,
379	    ) -> Range<usize> {
380	        let point_range = range.to_point(buffer);
381	        let patch = self.patch_for_buffer_range(point_range.start..=point_range.end, buffer);
382	        let start_point = patch.edit_for_old_position(point_range.start).new.start;
383	        let end_point = patch.edit_for_old_position(point_range.end).new.end;
384	        let base_text = self.base_text();
385	        let start = base_text.point_to_offset(start_point.min(base_text.max_point()));
386	        let end = base_text.point_to_offset(end_point.min(base_text.max_point()));
387	        start.min(end)..end
388	    }
389	
390	    pub fn hunks_intersecting_range_rev<'a>(
391	        &'a self,
392	        range: Range<Anchor>,
393	        buffer: &'a text::BufferSnapshot,
394	    ) -> impl 'a + Iterator<Item = DiffHunk> {
395	        let filter = move |summary: &DiffHunkSummary| {
396	            let before_start = summary.buffer_range.end.cmp(&range.start, buffer).is_lt();
397	            let after_end = summary.buffer_range.start.cmp(&range.end, buffer).is_gt();
398	            !before_start && !after_end
399	        };
400	        self.hunks_intersecting_range_rev_impl(filter, buffer)

