2184	    ///
2185	    /// Dropping the returned task cancels the update, leaving the diff
2186	    /// unchanged. Calls must not overlap; to re-run this when the buffer or
2187	    /// base text changes, store the task somewhere that the next call will
2188	    /// overwrite, so that the previous call is cancelled.
2189	    pub fn set_base_text(
2190	        &mut self,
2191	        base_text: Option<Arc<str>>,
2192	        buffer: text::BufferSnapshot,
2193	        cx: &mut Context<Self>,
2194	    ) -> Task<()> {
2195	        cx.spawn(async move |this, cx| {
2196	            let base_text_exists = base_text.is_some();
2197	            let base_text = base_text.unwrap_or_default();
2198	            let Some(base_text_diff) = this
2199	                .update(cx, |this, cx| {
2200	                    this.base_text_buffer.update(cx, |base_text_buffer, cx| {
2201	                        base_text_buffer.diff(base_text.clone(), cx)
2202	                    })
2203	                })
2204	                .log_err()
2205	            else {
2206	                return;
2207	            };
2208	            let base_text_diff = base_text_diff.await;
2209	            let Some(edited_base_text) = this
2210	                .update(cx, |this, cx| {
2211	                    if this.base_text_buffer.read(cx).version() != base_text_diff.base_version {
2212	                        log::warn!("dropping concurrent diff update");
2213	                        debug_panic!("incorrect concurrent call to set_base_text");
2214	                        return None;
2215	                    }
2216	                    let edited_base_text =
2217	                        this.base_text_buffer.update(cx, |base_text_buffer, cx| {
2218	                            base_text_buffer.set_line_ending(base_text_diff.line_ending, cx);
2219	                            assert!(base_text_buffer.version() == base_text_diff.base_version);
2220	                            base_text_buffer.snapshot_with_edits(base_text_diff.edits, cx)
2221	                        });
2222	                    Some(edited_base_text)
2223	                })
2224	                .log_err()
2225	                .flatten()
2226	            else {
2227	                return;
2228	            };
2229	            let edited_base_text = edited_base_text.await;
2230	            let base_text_snapshot = edited_base_text.snapshot().clone();
2231	            let Some(state) = this
2232	                .update(cx, |this, cx| {
2233	                    this.update_diff(
2234	                        buffer.clone(),
2235	                        &base_text_snapshot,
2236	                        base_text_exists.then(|| base_text.clone()),
2237	                        cx,
2238	                    )
2239	                })
2240	                .log_err()
2241	            else {
2242	                return;
2243	            };
2244	            let state = state.await;
2245	            this.update(cx, |this, cx| {
2246	                if &this.base_text_buffer.read(cx).version() != edited_base_text.base_version() {
2247	                    log::warn!("dropping concurrent diff update");
